#include "dx_iface.h"
#include <iostream>
#include <map>

int main(int argc, char** argv) {
    if (argc != 2) return 2;
    dx_data data;
    dx_iface input;
    const bool read = input.fileImport(argv[1], &data, false);
    std::map<std::uint32_t, unsigned> handles;
    for (const auto& x : data.lineTypes) if (x.handle != 0) ++handles[x.handle];
    for (const auto& x : data.dictionaries) if (x.handle != 0) ++handles[x.handle];
    for (const auto& x : data.xRecords) if (x.handle != 0) ++handles[x.handle];
    for (const auto& x : data.visualStyles) if (x.handle != 0) ++handles[x.handle];
    unsigned collisions = 0;
    for (const auto& x : handles) if (x.second > 1u) ++collisions;
    std::cout << "{\"read\":" << (read ? "true" : "false")
              << ",\"error\":" << static_cast<int>(data.dwgReadOutcome.error)
              << ",\"headerVars\":" << data.headerC.vars.size()
              << ",\"lineTypes\":" << data.lineTypes.size()
              << ",\"dictionaries\":" << data.dictionaries.size()
              << ",\"xrecords\":" << data.xRecords.size()
              << ",\"visualStyles\":" << data.visualStyles.size()
              << ",\"rawVisualStyles\":" << data.rawVisualStyleObjects.size()
              << ",\"evaluationGraphs\":" << data.evaluationGraphs.size()
              << ",\"hasNamedRoot\":" << (data.hasNamedObjectDictionary ? "true" : "false")
              << ",\"extensionSourceHandleCollisions\":" << collisions;
    for (const char* key : {"LUNITS", "INSUNITS", "LUPREC", "DIMDEC"}) {
        const auto found = data.headerC.vars.find(key);
        if (found != data.headerC.vars.end() && found->second != nullptr
            && found->second->type() == DRW_Variant::INTEGER)
            std::cout << ",\"" << key << "\":" << found->second->content.i;
    }
    std::cout << "}\n";
    return read ? 0 : 1;
}
